        raise ValueError("idle_days must be >= 1")
    on_hand: Dict[str, int] = {}
    last_ship: Dict[str, int] = {}
    first_mov: Dict[str, int] = {}
    for line in lines:
        s = line.strip()
        if not s or s.startswith("#"):
            continue
        rec = parse_movement_line(line, case_sizes)
        day, sku, qty, mtype = rec["day"], rec["sku"], rec["qty"], rec["type"]
        if day > today: continue
        on_hand[sku] = on_hand.get(sku, 0) + qty
        if sku not in first_mov or day < first_mov[sku]: first_mov[sku] = day
        if mtype == "SHP" and (sku not in last_ship or day > last_ship[sku]): last_ship[sku] = day
    dead = []
    for sku, qty in on_hand.items():
        if qty > 0:
            ref = last_ship.get(sku, first_mov.get(sku))
            if ref is not None and (today - ref) >= idle_days:
                dead.append(sku)
    return sorted(dead)"}}}
